        // current temperature (from temp sensor)
        in port current_tempWstatus : DataPort { :>> type : Isolette_Data_Model::TempWstatus_i; }

        // lowest and upper bound of desired temperature range
        in port lower_desired_temp : DataPort { :>> type : Isolette_Data_Model::Temp_i; }
